import{_ as t,o as r,c as a,ah as o}from"./chunks/framework.DDXs_i7t.js";const f=JSON.parse('{"title":"Research: The Horten-Alsberg Sales Contract (Duisburg 1936)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/der-kaufvertrag-horten-alsberg.md","filePath":"en/recherche/der-kaufvertrag-horten-alsberg.md"}'),n={name:"en/recherche/der-kaufvertrag-horten-alsberg.md"};function s(i,e,h,l,u,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="research-the-horten-alsberg-sales-contract-duisburg-1936" tabindex="-1">Research: The Horten-Alsberg Sales Contract (Duisburg 1936) <a class="header-anchor" href="#research-the-horten-alsberg-sales-contract-duisburg-1936" aria-label="Permalink to &quot;Research: The Horten-Alsberg Sales Contract (Duisburg 1936)&quot;">​</a></h1><p><strong>The foundation of an empire on the ruins of an existence.</strong></p><p>In the history of &quot;Aryanization,&quot; the takeover of the <strong>Gebrüder Alsberg</strong> department store in Duisburg by the then only 26-year-old Helmut Horten is considered the decisive moment that enabled his rise to become the &quot;department store king.&quot; For our mockumentary project, this contract is the &quot;smoking gun&quot; of historical evidence.</p><hr><h2 id="facts-on-the-contract" tabindex="-1">Facts on the Contract <a class="header-anchor" href="#facts-on-the-contract" aria-label="Permalink to &quot;Facts on the Contract&quot;">​</a></h2><h3 id="_1-date-and-location" tabindex="-1">1. Date and Location <a class="header-anchor" href="#_1-date-and-location" aria-label="Permalink to &quot;1. Date and Location&quot;">​</a></h3><ul><li><strong>Contract Date:</strong> April 23, 1936</li><li><strong>Effective Date (Change of Ownership):</strong> May 1, 1936</li><li><strong>Location:</strong> Duisburg</li></ul><h3 id="_2-the-contracting-parties" tabindex="-1">2. The Contracting Parties <a class="header-anchor" href="#_2-the-contracting-parties" aria-label="Permalink to &quot;2. The Contracting Parties&quot;">​</a></h3><ul><li><strong>Buyer:</strong> The newly founded <strong>Helmut Horten KG</strong>. Helmut Horten was the sole personally liable partner. The purchase was largely financed by loans from the Commerz- und Privatbank.</li><li><strong>Sellers:</strong> The Jewish owners of the <strong>Gebrüder Alsberg OHG</strong> (Duisburg branch), namely <strong>Hermann Strauß</strong> as well as <strong>Ernst and Curt Lauter</strong>. (Amalie Lauter, another partner, was unable to flee and was later murdered in the Holocaust).</li></ul><h3 id="_3-purchase-price-and-scope" tabindex="-1">3. Purchase Price and Scope <a class="header-anchor" href="#_3-purchase-price-and-scope" aria-label="Permalink to &quot;3. Purchase Price and Scope&quot;">​</a></h3><p>According to later restitution files, the total purchase price was <strong>672,963.65 Reichsmark (RM)</strong>.</p><ul><li>The bulk of the sum (nearly 672,000 RM) was for the warehouse inventory.</li><li>Critics and historians point out that the price was established under the pressure of the systematic displacement of Jewish entrepreneurs. Horten paid, but he paid in a market where the sellers had no choice.</li></ul><hr><h2 id="historical-context-aryanization-or-fair-business" tabindex="-1">Historical Context: &quot;Aryanization&quot; or &quot;Fair Business&quot;? <a class="header-anchor" href="#historical-context-aryanization-or-fair-business" aria-label="Permalink to &quot;Historical Context: &quot;Aryanization&quot; or &quot;Fair Business&quot;?&quot;">​</a></h2><h3 id="the-hoeres-report-2022" tabindex="-1">The Hoeres Report (2022) <a class="header-anchor" href="#the-hoeres-report-2022" aria-label="Permalink to &quot;The Hoeres Report (2022)&quot;">​</a></h3><p>A comprehensive scientific report by historian <strong>Prof. Dr. Peter Hoeres</strong> (University of Würzburg), commissioned by the Horten Foundation, concluded in 2022 that while Horten was &quot;not a Nazi ideologue,&quot; he was undoubtedly an <strong>&quot;opportunistic profiteer&quot;</strong> of the system of injustice.</p><h3 id="official-documents-sources-pdf-downloads" tabindex="-1">Official Documents &amp; Sources (PDF Downloads) <a class="header-anchor" href="#official-documents-sources-pdf-downloads" aria-label="Permalink to &quot;Official Documents &amp; Sources (PDF Downloads)&quot;">​</a></h3><p>For the historical substantiation of our project, we rely on the official publications of the Helmut Horten Foundation:</p><ul><li>📄 <strong><a href="https://www.helmut-horten-stiftung.org/fileadmin/user_upload/Gutachten_Horten_Hoeres_Kutzner.pdf" target="_blank" rel="noreferrer">Full Report (PDF)</a></strong> – <em>&quot;On the wealth and business development of Helmut Horten&quot;</em> (Prof. Dr. Peter Hoeres &amp; Dr. Maximilian Kutzner).</li><li>📄 <strong><a href="https://www.helmut-horten-stiftung.org/fileadmin/user_upload/Zusammenfassung_Gutachten_Horten_Hoeres_Kutzner.pdf" target="_blank" rel="noreferrer">Summary of the Report (PDF)</a></strong> – The main theses at a glance.</li><li>🌐 <strong><a href="https://www.helmut-horten-stiftung.org/" target="_blank" rel="noreferrer">Official Website of the Helmut Horten Foundation</a></strong> – Historical processing of the legacy.</li></ul><hr><h2 id="the-fate-of-the-original-contract" tabindex="-1">The Fate of the Original Contract <a class="header-anchor" href="#the-fate-of-the-original-contract" aria-label="Permalink to &quot;The Fate of the Original Contract&quot;">​</a></h2><p>While many original documents from the 1930s were lost during the war or during denazification, the core data of the Duisburg purchase (price: 672,963.65 RM) is historically authenticated through the detailed reconstruction in the Hoeres Report and through post-war restitution files.</p><hr><p><em>Source: Gutachten über den Vermögens- und Geschäftsaufbau von Helmut Horten (2022), Helmut Horten Foundation.</em></p>',24)])])}const g=t(n,[["render",s]]);export{f as __pageData,g as default};
